    // Set failure defaults immediately as per contract
    if (loss != NULL) {
        *loss = INFINITY;
    }
    if (worst_index != NULL) {
        *worst_index = SIZE_MAX;
    }

    // Validate complete input before committing outputs
    if ((c_bi == NULL) || (body_vectors == NULL) || 
        (inertial_vectors == NULL) || (weights == NULL) || 
        (loss == NULL) || (worst_index == NULL)) {
        return ADCS_E_NULL;
    }

    // Count must be in 1..32
    if ((count < 1) || (count > 32)) {
        return ADCS_E_RANGE;
    }

    // Validate matrix is finite
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            if (!isfinite(c_bi->m[i][j])) {
                return ADCS_E_RANGE;
            }
        }
    }

    double weighted_loss_sum = 0.0;
    double weight_sum = 0.0;
    double residuals[32];

    for (size_t k = 0; k < count; ++k) {
        // Validate weight: positive and finite
        if ((!isfinite(weights[k])) || (weights[k] <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Validate vectors are finite
        if (!adcs_is_finite_vec3(&body_vectors[k]) || !adcs_is_finite_vec3(&inertial_vectors[k])) {
            return ADCS_E_RANGE;
        }

        // Normalize body vector
        adcs_vec3_t b_k;
        if (adcs_vec3_normalize(&body_vectors[k], ADCS_EPS_NORM, &b_k) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Normalize inertial vector
        adcs_vec3_t r_k;
        if (adcs_vec3_normalize(&inertial_vectors[k], ADCS_EPS_NORM, &r_k) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Predicted body vector: C_BI * r_k
        adcs_vec3_t predicted_k = adcs_mat3_mul_vec(c_bi, &r_k);

        // Normalize predicted vector
        adcs_vec3_t pred_normed;
        if (adcs_vec3_normalize(&predicted_k, ADCS_EPS_NORM, &pred_normed) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Residual e_k = 1 - b_k . predicted_k
        double dot_product = adcs_vec3_dot(&b_k, &pred_normed);
        double e_k = 1.0 - dot_product;

        residuals[k] = e_k;

        // Accumulate deterministically
        weighted_loss_sum += weights[k] * e_k;
        weight_sum += weights[k];
    }

    // Calculate weighted mean loss
    if (weight_sum <= 0.0) {
        return ADCS_E_RANGE;
    }
    *loss = weighted_loss_sum / weight_sum;

    // Find worst observation: largest unweighted e_k, ties select lowest index
    size_t worst_idx = SIZE_MAX;
    double max_e_k = -1.0;

    for (size_t k = 0; k < count; ++k) {
        if (residuals[k] > max_e_k) {
            max_e_k = residuals[k];
            worst_idx = k;
        }
    }

    *worst_index = worst_idx;

    return ADCS_OK;
}

